function Field({label,icon,value,onChange,placeholder='',type='text'}:{label:string;icon:any;value:any;onChange:(v:string)=>void;placeholder?:string;type?:string}){return <label className="field"><span>{label}</span><div className="field-input">{icon}<input type={type} min={type==='number'?0:undefined} value={value??''} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></div></label>}
