  useEffect(()=>{const term=query.trim();if(value||term.length<2){setResults([]);setLoading(false);setError('');return}let ignore=false;setLoading(true);setError('');setResults([]);setActiveIndex(0);const timer=window.setTimeout(()=>{api(`/hotels/places/search?q=${encodeURIComponent(term)}`).then(response=>{if(ignore)return;const rows=Array.isArray(response.data)?response.data.filter((place:unknown)=>place&&typeof place==='object'&&typeof (place as HotelPlace).place_id==='string'&&typeof (place as HotelPlace).display_name==='string') as HotelPlace[]:[];setResults(rows)}).catch((reason:unknown)=>{if(!ignore)setError(reason instanceof Error?reason.message:'Hotel location search failed. Please try again.')}).finally(()=>{if(!ignore)setLoading(false)})},300);return()=>{ignore=true;window.clearTimeout(timer)}},[query,value]);
  const choose=(place:HotelPlace)=>{onChange(place);setQuery('');setResults([]);setError('');setOpen(false);setActiveIndex(0)};
  const clear=()=>{onChange(null);setQuery('');setResults([]);setError('');setOpen(true);inputRef.current?.focus()};
