function AirportAutocomplete({label,value,onChange}:{label:string;value:Airport|null;onChange:(airport:Airport|null)=>void}){
  const [query,setQuery]=useState(''),[results,setResults]=useState<Airport[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(''),[open,setOpen]=useState(false),[activeIndex,setActiveIndex]=useState(0);
  const inputRef=useRef<HTMLInputElement>(null);
  const id=`airport-${label.toLowerCase().replace(/\W+/g,'-')}`;
  const display=(airport:Airport)=>`${airport.airport_name} - ${airport.city_name||'City not listed'}, ${airport.country_name||airport.country_code} (${airport.iata_code})`;
  useEffect(()=>{
    const term=query.trim();
    if(value||term.length<2){setResults([]);setLoading(false);setError('');return}
    let ignore=false;
    setLoading(true);setError('');setResults([]);setActiveIndex(0);
    const timer=window.setTimeout(()=>{
      api(`/airports/search?q=${encodeURIComponent(term)}&limit=10`).then(response=>{
        if(ignore)return;
        const rows=Array.isArray(response.data)?response.data.filter((row:unknown)=>row&&typeof row==='object'&&typeof (row as Airport).iata_code==='string') as Airport[]:[];
        setResults(rows);
      }).catch((reason:unknown)=>{if(!ignore)setError(reason instanceof Error?reason.message:'Airport search failed. Please try again.')}).finally(()=>{if(!ignore)setLoading(false)});
    },300);
    return ()=>{ignore=true;window.clearTimeout(timer)};
  },[query,value]);
  const choose=(airport:Airport)=>{onChange(airport);setQuery('');setResults([]);setError('');setOpen(false);setActiveIndex(0)};
  const clear=()=>{onChange(null);setQuery('');setResults([]);setError('');setOpen(true);inputRef.current?.focus()};
  const handleKeyDown=(event:React.KeyboardEvent<HTMLInputElement>)=>{
    if(event.key==='ArrowDown'&&results.length){event.preventDefault();setOpen(true);setActiveIndex(index=>(index+1)%results.length)}
    else if(event.key==='ArrowUp'&&results.length){event.preventDefault();setOpen(true);setActiveIndex(index=>(index-1+results.length)%results.length)}
    else if(event.key==='Enter'&&open&&results[activeIndex]){event.preventDefault();choose(results[activeIndex])}
    else if(event.key==='Escape'){setOpen(false)}
  };
  return <div className="airport-autocomplete field"><label htmlFor={`${id}-input`}><span>{label} AIRPORT</span></label><div className="airport-input-wrap"><MapPin size={16}/><input ref={inputRef} id={`${id}-input`} role="combobox" aria-autocomplete="list" aria-expanded={open&&!value&&query.trim().length>=2} aria-controls={`${id}-list`} aria-activedescendant={open&&results[activeIndex]?`${id}-option-${activeIndex}`:undefined} autoComplete="off" value={value?display(value):query} placeholder="Search city or airport" onFocus={()=>setOpen(true)} onBlur={()=>window.setTimeout(()=>setOpen(false),120)} onChange={event=>{setQuery(event.target.value);onChange(null);setOpen(true)}} onKeyDown={handleKeyDown}/>{(value||query)&&<button className="airport-clear" type="button" aria-label={`Clear ${label.toLowerCase()} airport`} onMouseDown={event=>event.preventDefault()} onClick={clear}><X size={15}/></button>}</div>
    {open&&!value&&(loading||error||query.trim().length>=2)&&<div className="airport-dropdown" id={`${id}-list`} role="listbox" aria-label={`${label.toLowerCase()} airport suggestions`}>
      {loading&&<div className="airport-feedback" role="status">Searching airports...</div>}{error&&<div className="airport-feedback airport-error" role="alert">{error}</div>}
      {!loading&&!error&&query.trim().length>=2&&!results.length&&<div className="airport-feedback" role="status">No matching airports. Try another city or airport name.</div>}
      {!loading&&results.map((airport,index)=><button type="button" role="option" aria-selected={index===activeIndex} id={`${id}-option-${index}`} className={`airport-option ${index===activeIndex?'active':''}`} key={airport.iata_code} onMouseEnter={()=>setActiveIndex(index)} onMouseDown={event=>event.preventDefault()} onClick={()=>choose(airport)}><span><b>{airport.airport_name}</b><small>{airport.city_name||airport.subdivision||'City not listed'}, {airport.country_name||airport.country_code}</small></span><strong>{airport.iata_code}</strong></button>)}
    </div>}
    {value&&<div className="airport-selected" aria-live="polite"><b>{value.city_name||value.subdivision||'Airport'}</b><span>{value.airport_name} - {value.country_name||value.country_code} - {value.iata_code}</span></div>}
    {!value&&query.trim().length===1&&<span className="airport-hint">Enter at least two characters.</span>}
  </div>;
}

function PageHeader({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:any}){return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function TripRow({trip,onClick}:{trip:Trip;onClick:()=>void}){const r=trip.travel_request;return <button className="trip-row" onClick={onClick}><div className="trip-icon"><MapPin size={19}/></div><div className="trip-main"><b>{r.origin||'Origin'} <span>→</span> {r.destination||'Destination'}</b><small>{dateFmt(r.departure_date)} {r.return_date?`– ${dateFmt(r.return_date)}`:''} · {r.adults||1} travelers</small></div><span className={`trip-status ${r.status==='ready_to_search'?'ready':''}`}>{r.status==='ready_to_search'?'Ready':'In progress'}</span><ArrowRight className="row-arrow" size={17}/></button>}
