function Empty({icon,title,text,action,onClick}:{icon:any;title:string;text:string;action:string;onClick:()=>void}){return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p><button className="secondary" onClick={onClick}>{action} <ArrowRight size={14}/></button></div>}
function Quick({icon,title,text,onClick}:{icon:any;title:string;text:string;onClick:()=>void}){return <button className="quick-link" onClick={onClick}><div>{icon}</div><span><b>{title}</b><small>{text}</small></span><ArrowRight size={15}/></button>}

function FlightCard({journey,offer,criteria,tripId,onError,onNotice,checkoutEnabled}:{journey:FlightJourney;offer:FlightOffer;criteria?:FlightSearchCriteria;tripId:string;onError:(s:string)=>void;onNotice:(s:string)=>void;checkoutEnabled:boolean}){
  const validation=validateJourneyRoute(journey,criteria);
  const airlines=[...new Set((journey.segments||[]).map(segment=>{const carrier=segment.carrier;const name=carrier?.marketingName||carrier?.operatingName;const code=carrier?.marketingCode||carrier?.operatingCode;return name?(code?`${name} (${code})`:name):code||''}).filter(Boolean))];
  const flightNumbers=[...new Set((journey.segments||[]).map(segment=>segment.flight?.marketingNumber||segment.flight?.operatingNumber).filter(Boolean))];
  const price=offer.pricing?.display?.total;const currency=offer.pricing?.display?.currency||criteria?.currency||'';
  const baggage=formatIncludedBaggage(offer.baggage?.included);
  const expiry=offer.expiration?new Date(offer.expiration).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}):'';
  const [verified,setVerified]=useState<any>(null),[checkout,setCheckout]=useState<any>(null),[busy,setBusy]=useState(false),[changedFare,setChangedFare]=useState(false),[status,setStatus]=useState('Search result');
  const verifiedPrice=verified?.price??verified?.data?.pricing?.display?.total??verified?.data?.price??price;
  const verifiedCurrency=verified?.currency??verified?.data?.pricing?.display?.currency??verified?.data?.currency??currency;
  async function verify(){if(!offer.offerId)return onError('The provider did not return an offer ID, so this fare cannot be verified.');setBusy(true);onError('');try{const r=await api(`/trips/${tripId}/flights/verify`,{method:'POST',body:JSON.stringify({offer_id:offer.offerId})});setVerified(r);setCheckout(null);setChangedFare(false);setStatus('Verified offer');onNotice(`Fare verified${r.data?.pricing?.display?.total?`: ${r.data.pricing.display.currency||''} ${r.data.pricing.display.total}`:''}. Review the current fare and conditions before checkout.`)}catch(e:any){setStatus('Search result');onError(e.message)}finally{setBusy(false)}}
  async function prebook(payload:any){if(!verified?.verification_id||!checkoutEnabled||busy)return;const expiry=verified.data?.expiration;if(expiry&&Number.isFinite(Date.parse(expiry))&&Date.parse(expiry)<=Date.now()){setVerified(null);setStatus('Verified fare expired · verify again');onError('This verified offer expired. Verify the exact offer again before entering checkout.');return}setBusy(true);onError('');try{const result=await api(`/trips/${tripId}/flights/prebook`,{method:'POST',body:JSON.stringify({offer_id:offer.offerId,verification_id:verified.verification_id,contact:payload.contact,passengers:payload.passengers,confirm_price:true})});setCheckout({...result,offer_id:offer.offerId});setStatus('Prebook created · payment pending');setChangedFare(false)}catch(e:any){const detail=(e as Error&{details?:any}).details;if(detail?.code==='FLIGHT_PRICE_CHANGED'){setVerified((current:any)=>({...current,verification_id:detail.verification_id,price:detail.price,currency:detail.currency,data:{...current?.data,expiration:detail.expiration}}));setChangedFare(true);setStatus('Price changed · reconfirmation required');onError(`${detail.message} New provider price: ${detail.currency||''} ${detail.price??'unavailable'}. Review it, then confirm again.`)}else if(detail?.code==='FLIGHT_OFFER_EXPIRED'){setVerified(null);setStatus('Offer expired · verify a current offer');onError(detail.message||'This provider offer expired. Verify a current offer before checkout.')}else{onError(e.message);if(detail?.code==='FLIGHT_ACCESS_DISABLED')setStatus('Flight access unavailable')}}finally{setBusy(false)}}
  return <article className="flight-card flight-offer-card">
    <div className="flight-offer-heading"><div className="flight-brand"><div className="airline-mark"><Plane/></div><div><b>{airlines.join(', ')||'Airline information unavailable'}</b>{flightNumbers.length>0&&<small>Flights {flightNumbers.join(', ')}</small>}</div></div><div className="offer-expiry">{expiry?<>Offer expiry <b>{expiry}</b></>:'Offer expiry unavailable'}</div></div>
    <div className="flight-legs"><FlightLeg title="Outbound" segments={validation.outbound} journey={journey}/>{validation.inbound.length>0&&<FlightLeg title="Return" segments={validation.inbound} journey={journey}/>}</div>
    <aside className="flight-fare-panel"><span className="offer-kind">{criteria?.legs.length===1?'ONE WAY TOTAL':'ROUND TRIP TOTAL'}</span><b className="flight-total">{(verifiedPrice??price)!=null?`${verifiedCurrency} ${Number(verifiedPrice??price).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`:'Price unavailable'}</b><small className="baggage-summary">{baggage}</small><small className="flight-step-status">Status: {status}</small><button className="secondary" onClick={verify} disabled={!offer.offerId||busy}>{busy?'Verifying…':'Verify fare & select'}</button><small className="fare-note">Search results are not a booking. Verification checks current provider price and availability.</small></aside>
    {verified&&!checkout&&<div className="flight-checkout-area"><div className="flight-verified-summary"><b>Verified itinerary · {verifiedCurrency} {verifiedPrice??'price unavailable'}</b><small>Review the exact route, current provider fare, baggage and any fare changes before entering traveler details.</small>{verified.data?.changes&&<pre>{JSON.stringify(verified.data.changes,null,2)}</pre>}</div>{checkoutEnabled?<FlightPassengerForm criteria={criteria} busy={busy} changedFare={changedFare} onPrebook={prebook}/>:<div className="alert error">Checkout remains disabled until Flights access, payment SDK availability and the server-side sandbox checkout gates are all confirmed.</div>}</div>}
    {checkout&&<div className="flight-checkout-area"><div className="flight-verified-summary"><b>Provider prebook · {checkout.currency} {checkout.price}</b><small>Prebook status: {checkout.status} · Provider ID: {checkout.prebook_id}</small><small>Exact offer ID: {offer.offerId}</small><small>Itinerary and baggage reviewed above · no booking is confirmed yet.</small>{checkout.client_reference&&<small>Wayfarer reference: {checkout.client_reference}</small>}</div>{checkout.secret_key&&checkout.transaction_id&&<LiteApiPayment key={checkout.prebook_id} secretKey={checkout.secret_key} transactionId={checkout.transaction_id} prebookId={checkout.prebook_id}/>}</div>}
  </article>;
}

function FlightPassengerForm({criteria,busy,changedFare,onPrebook}:{criteria?:FlightSearchCriteria;busy:boolean;changedFare:boolean;onPrebook:(payload:any)=>Promise<void>}) {
  const adults=criteria?.adults||1,children=criteria?.children||0,infants=criteria?.infants||0;
  const types=[...Array(adults).fill(0),...Array(children).fill(1),...Array(infants).fill(2)];
  const [contact,setContact]=useState({firstName:'',lastName:'',email:'',phoneCountryCode:'',phoneNumber:''});
  const [passengers,setPassengers]=useState(()=>types.map(passengerType=>({passengerType,firstName:'',lastName:'',birthday:'',gender:'',nationality:'',documentType:'passport',documentNumber:'',documentIssueCountry:'',documentExpiry:''})));
  const [confirm,setConfirm]=useState(false),[submitting,setSubmitting]=useState(false);
  useEffect(()=>{if(changedFare)setConfirm(false)},[changedFare]);
  const editContact=(key:string,value:string)=>setContact(current=>({...current,[key]:value}));
  const editPassenger=(index:number,key:string,value:string)=>setPassengers(current=>current.map((row,i)=>i===index?{...row,[key]:value}:row));
  const valid=Boolean(contact.firstName.trim()&&contact.lastName.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact.email)&&contact.phoneCountryCode.trim()&&contact.phoneNumber.trim()&&passengers.every(p=>p.firstName.trim()&&p.lastName.trim()&&p.birthday&&p.gender&&/^[A-Za-z]{2}$/.test(p.nationality)&&p.documentNumber.trim()&&/^[A-Za-z]{2}$/.test(p.documentIssueCountry)&&p.documentExpiry));
  const submit=async(event:React.FormEvent)=>{event.preventDefault();if(!valid||!confirm||busy||submitting)return;setSubmitting(true);try{await onPrebook({contact,passengers})}finally{setSubmitting(false)}};
  return <form className="flight-passenger-form" onSubmit={submit}>
    <h3>Passenger and contact details</h3>
    <div className="flight-contact-fields">{(['firstName','lastName','email','phoneCountryCode','phoneNumber'] as const).map(key=><label key={key}>{({firstName:'Contact first name',lastName:'Contact last name',email:'Contact email',phoneCountryCode:'Phone country code',phoneNumber:'Phone number'})[key]}<input required type={key==='email'?'email':'text'} value={contact[key]} onChange={event=>editContact(key,event.target.value)}/></label>)}</div>
    {passengers.map((passenger,index)=><section className="flight-passenger" key={index}><b>Passenger {index+1} · {passenger.passengerType===0?'Adult':passenger.passengerType===1?'Child':'Infant'}</b><div className="flight-contact-fields">{(['firstName','lastName','birthday','gender','nationality','documentNumber','documentIssueCountry','documentExpiry'] as const).map(key=><label key={key}>{({firstName:'First name',lastName:'Last name',birthday:'Date of birth',gender:'Gender',nationality:'Nationality (ISO 2-letter)',documentNumber:'Passport number',documentIssueCountry:'Passport issuing country',documentExpiry:'Passport expiry'})[key]}{key==='gender'?<select required value={passenger.gender} onChange={event=>editPassenger(index,key,event.target.value)}><option value="">Select</option><option value="M">M</option><option value="F">F</option></select>:<input required type={key==='birthday'||key==='documentExpiry'?'date':'text'} autoComplete="off" value={passenger[key]} max={key==='birthday'?criteria?.legs[0]?.date:undefined} min={key==='documentExpiry'?criteria?.legs[0]?.date:undefined} onChange={event=>editPassenger(index,key,event.target.value)}/>}</label>)}</div></section>)}
    <p className="muted">Passenger and passport details are sent to LiteAPI only to create this prebook and are not saved in the Wayfarer checkout record. Do not enter card details here.</p>
    <label className="confirm-check"><input type="checkbox" checked={confirm} onChange={event=>setConfirm(event.target.checked)}/>{changedFare?'I reviewed and accept the updated provider fare. Create this sandbox prebook.':'I reviewed the exact itinerary, verified fare, baggage and conditions. Create this sandbox prebook and continue to secure LiteAPI payment.'}</label>
    <button className="primary" type="submit" disabled={!valid||!confirm||busy||submitting}>{busy||submitting?'Creating prebook…':changedFare?'Confirm updated fare & prebook':'Confirm fare & create sandbox prebook'}</button>
  </form>;
}

function LiteApiPayment({secretKey,transactionId,prebookId}:{secretKey:string;transactionId:string;prebookId:string}) {
  const targetId=useId().replace(/:/g,'');
  const [status,setStatus]=useState('Loading the secure LiteAPI payment form…'),[error,setError]=useState('');
  useEffect(()=>{
    const Payment=window.LiteAPIPayment;
    if(!Payment){setError('The LiteAPI payment SDK did not load. Do not retry the prebook; reload the checkout only after checking its status.');return}
    const timeout=window.setTimeout(()=>setStatus('Payment is taking longer than expected. This is not a confirmation; do not submit another prebook or booking. Check the provider payment status before proceeding.'),90_000);
    const returnUrl=`${window.location.origin}${window.location.pathname}?tid=${encodeURIComponent(transactionId)}&pid=${encodeURIComponent(prebookId)}`;
    try{
      const widget=new Payment({publicKey:'sandbox',appearance:{theme:'flat'},options:{business:{name:'Wayfarer'}},targetElement:`#${targetId}`,secretKey,returnUrl});
      const result=widget.handlePayment();
      setStatus('Complete payment in the secure LiteAPI form. The SDK returns here after successful payment; do not refresh or submit another prebook while it is processing.');
      if(result&&typeof result.then==='function')void result.catch(()=>setError('The payment SDK could not complete checkout. Use the message in the secure payment form; do not submit a duplicate prebook.'));
    }catch{setError('The secure LiteAPI payment form could not be initialized. Do not create another prebook; check its status before proceeding.')}
    return ()=>window.clearTimeout(timeout);
  },[prebookId,secretKey,targetId,transactionId]);
  return <section className="liteapi-payment-form"><h3>Sandbox payment · LiteAPI Payment SDK</h3><p>Use sandbox test card <b>4242 4242 4242 4242</b>, any three-digit CVC and a future expiry date. Card data is entered only in the provider-hosted SDK form, never sent to Wayfarer.</p><div id={targetId}/><small role="status">{status}</small>{error&&<div className="alert error">{error}</div>}</section>;
}
function FlightLeg({title,segments,journey}:{title:string;segments:FlightSegment[];journey:FlightJourney}){
  const first=segments[0],last=segments[segments.length-1];
  const direction=title==='Outbound'?'OUTBOUND':'INBOUND';
  const connections=journey.connections?.filter(connection=>(connection.direction||'').toUpperCase()===direction)||[];
  const segmentMinutes=segments.reduce((sum,segment)=>sum+(segment.duration?.minutes||0),0);
  const duration=journey.legDurations?.find(leg=>(leg.direction||'').toUpperCase()===direction)?.duration||(segmentMinutes>0?{minutes:segmentMinutes}:undefined);
  const stops=connections.length||Math.max(0,segments.length-1);
  const airport=(code?:string,name?:string)=>code?`${code}${name?` - ${name}`:''}`:'Airport information unavailable';
  const nextDay=Boolean(first?.departureTime&&last?.arrivalTime&&first.departureTime.slice(0,10)!==last.arrivalTime.slice(0,10));
  return <section className="flight-leg"><div className="flight-leg-header"><b>{title}</b><span>{stops===0?'Nonstop':`${stops} stop${stops===1?'':'s'}`} - {formatDuration(duration)}</span></div><div className="flight-leg-endpoints"><div><strong>{airport(first?.originCode,first?.originName)}</strong><small>{formatFlightDateTime(first?.departureTime)}</small></div><span className="leg-arrow">to</span><div><strong>{airport(last?.destinationCode,last?.destinationName)}</strong><small>{formatFlightDateTime(last?.arrivalTime)}{nextDay&&<em className="next-day-label">Next day arrival</em>}</small></div></div>{stops>0&&<div className="flight-segment-list">{segments.map((segment,index)=><div className="flight-segment" key={`${segment.originCode||'from'}-${segment.destinationCode||'to'}-${index}`}><span><b>{segment.originCode||'Unknown'} to {segment.destinationCode||'Unknown'}</b><small>{formatFlightDateTime(segment.departureTime)} to {formatFlightDateTime(segment.arrivalTime)}</small></span><small>{segment.carrier?.marketingName||segment.carrier?.operatingName||segment.carrier?.marketingCode||segment.carrier?.operatingCode||'Airline information unavailable'}{segment.flight?.marketingNumber?` - ${segment.flight.marketingNumber}`:''}</small></div>)}</div>}{connections.length>0&&<div className="flight-layovers">{connections.map((connection,index)=><span key={`${connection.arrivalAirportCode||'stop'}-${index}`}>Connection at {connection.arrivalAirportCode||'airport unavailable'} - layover {formatDuration(connection.duration)}</span>)}</div>}</section>;
}
function BookingRow({data,type}:{data:any;type:string}){const itinerary=Array.isArray(data.itinerary)?data.itinerary.map((leg:any)=>`${leg.origin||'?'} → ${leg.destination||'?'}${leg.date?` · ${dateFmt(leg.date)}`:''}`).join(' / '):'';const passengerCount=typeof data.passenger_count==='number'?data.passenger_count:undefined;return <div className="booking-row"><div className="booking-type">{type==='Hotel'?<Hotel/>:<Plane/>}</div><div className="booking-main"><b>{data.hotel_name||data.provider||type+' booking'}</b><small>{itinerary|| (data.checkin?`${dateFmt(data.checkin)} – ${dateFmt(data.checkout)}`:data.confirmation_reference||data.confirmation_code||'')}</small>{passengerCount!==undefined&&<small>{passengerCount} passenger{passengerCount===1?'':'s'}{data.passenger_counts?` · ${data.passenger_counts.adults||0} adults, ${data.passenger_counts.children||0} children, ${data.passenger_counts.infants||0} infants`:''}</small>}<small>Provider booking ID: {data.provider_booking_id||'Not returned'}{data.confirmation_reference?` · Booking ref: ${data.confirmation_reference}`:''}{data.client_reference?` · Client ref: ${data.client_reference}`:''}</small>{(data.created_at||data.attempted_at)&&<small>Submitted {new Date(data.created_at||data.attempted_at).toLocaleString()}</small>}{type==='Hotel'&&data.status==='CONFIRMED_SANDBOX'&&data.is_sandbox&&<HotelServiceControls data={data}/>}</div><span className={`booking-status ${String(data.status).includes('CONFIRMED')||data.status==='CONFIRMED'?'confirmed':''}`}>{data.status||'Unknown'}</span><span className="booking-price">{data.selling_price!=null?`${data.currency||''} ${data.selling_price}`:data.price!=null?`${data.currency||''} ${data.price}`:''}</span><small className="environment-tag">{data.is_sandbox?'SANDBOX':data.provider||'Local record'}</small></div>}
function HotelServiceControls({data}:{data:any}){const [mode,setMode]=useState<'cancel'|'amend'|null>(null),[preview,setPreview]=useState<any>(null),[result,setResult]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[confirmed,setConfirmed]=useState(false),[first,setFirst]=useState(''),[last,setLast]=useState(''),[email,setEmail]=useState('');const url=`/trips/${encodeURIComponent(data.trip_id)}/hotels/bookings/${encodeURIComponent(data.booking_id||data.provider_booking_id)}`;const openCancel=async()=>{setMode('cancel');setResult(null);setError('');setConfirmed(false);setBusy(true);try{setPreview(await api(`${url}/service-preview`))}catch(e:any){setError(readableError((e as Error&{details?:unknown}).details)||e.message)}finally{setBusy(false)}};const cancel=async()=>{if(!preview?.preview_token||!confirmed)return;setBusy(true);setError('');try{const value=await api(`${url}/cancel`,{method:'POST',body:JSON.stringify({preview_token:preview.preview_token,confirm_cancellation:true})});setResult(value);window.dispatchEvent(new Event('wayfarer-booking-refresh'))}catch(e:any){setError(readableError((e as Error&{details?:unknown}).details)||e.message)}finally{setBusy(false)}};const verify=async()=>{setBusy(true);setError('');try{setResult(await api(`${url}/cancel/verify`,{method:'POST'}));window.dispatchEvent(new Event('wayfarer-booking-refresh'))}catch(e:any){setError(readableError((e as Error&{details?:unknown}).details)||e.message)}finally{setBusy(false)}};const amend=async(event:React.FormEvent)=>{event.preventDefault();if(!confirmed)return;setBusy(true);setError('');try{const value=await api(`${url}/amend-holder`,{method:'POST',body:JSON.stringify({first_name:first,last_name:last,email,confirm_amendment:true})});setResult(value)}catch(e:any){setError(readableError((e as Error&{details?:unknown}).details)||e.message)}finally{setBusy(false)}};const policy=preview?.cancellation_policy;const terms=Array.isArray(policy)?policy.map((term:any)=>typeof term==='string'?term:[term.cancelTime||term.cancel_time,term.amount!=null?`${term.amount} ${term.currency||preview.currency||''}`:null,term.type].filter(Boolean).join(' · ')).filter(Boolean).join(' / '):policy&&typeof policy==='object'?[policy.cancelTime||policy.cancel_time,policy.amount!=null?`${policy.amount} ${policy.currency||preview.currency||''}`:null,policy.type].filter(Boolean).join(' · '):typeof policy==='string'?policy:'Provider did not return a readable cancellation policy. Contact the provider if fee or refund details are unclear.';return <div className="hotel-service-controls"><button className="text-button" onClick={openCancel}>Review cancellation</button><button className="text-button" onClick={()=>{setMode('amend');setPreview(null);setResult(null);setError('');setConfirmed(false)}}>Change booking holder</button>{mode&&<section className="hotel-service-panel"><div className="service-panel-heading"><b>{mode==='cancel'?'Cancellation review':'Amend booking holder'}</b><button type="button" className="text-button" onClick={()=>setMode(null)}>Close</button></div>{busy&&<small>Checking provider status…</small>}{mode==='cancel'&&preview&&<><p><b>{preview.hotel_name||data.hotel_name}</b> · {preview.checkin?`${dateFmt(preview.checkin)} – ${dateFmt(preview.checkout)}`:'Stay dates unavailable'}</p><p>Current provider status: {preview.provider_status}. Booking reference: {preview.booking_reference||'not returned'}.</p><p>Provider cancellation terms: {terms}</p>{preview.provider_status==='CONFIRMED'&&<><label className="confirm-check"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/>I reviewed the current provider terms and explicitly authorize cancellation of this booking.</label><button className="primary" disabled={!confirmed||busy} onClick={cancel}>{busy?'Submitting…':'Confirm hotel cancellation'}</button></>}{preview.provider_status!=='CONFIRMED'&&<div className="alert error">The provider does not currently report this booking as confirmed; cancellation is disabled.</div>}</>}{mode==='amend'&&<form onSubmit={amend}><p>LiteAPI supports changes to the booking holder’s first name, last name and email only. Other guest or itinerary changes are not available through this amendment.</p><div className="checkout-fields"><label>New holder first name<input required value={first} onChange={event=>setFirst(event.target.value)}/></label><label>New holder last name<input required value={last} onChange={event=>setLast(event.target.value)}/></label><label>New holder email<input required type="email" value={email} onChange={event=>setEmail(event.target.value)}/></label></div><label className="confirm-check"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/>I reviewed and authorize this booking-holder amendment.</label><button className="primary" type="submit" disabled={!confirmed||busy}>{busy?'Submitting…':'Confirm holder amendment'}</button></form>}{result&&<div className="alert success">Provider servicing status: {result.provider_status||result.status||'Unknown'}{result.cancellation_fee!=null?` · Cancellation fee ${result.currency||''} ${result.cancellation_fee}`:''}{result.refund_amount!=null?` · Refund amount ${result.currency||''} ${result.refund_amount}`:''}{result.status==='REQUIRES_RECONCILIATION'&&mode==='cancel'&&<button className="secondary" onClick={verify} disabled={busy}>Recheck cancellation status</button>}</div>}{error&&<div className="alert error">{error}</div>}</section>}</div>}
